2	  import { onMount } from 'svelte';
3	  import { apiFetch, ApiError } from '../lib/api';
4	  import { getWorksheetData } from '../lib/tableau';
5	  import { sessionStore } from '../stores/session.svelte';
6	  import { dataStore, extractAvailableDays, extractAvailableRows } from '../stores/data.svelte';
7	
8	  const sessionHeaders = (): Record<string, string> =>
9	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
10	
11	  type WorksheetConfig = {
12	    worksheetName: string | null;
13	    availableDaysColumn: string | null;
14	    availabilityColumn: string | null;
15	    availabilityValue: string | null;
16	  };
17	
18	  // Returns worksheet config from /api/config/workflow, or nulls if not set.
19	  // Throws ApiError/Error if the config endpoint is unreachable.
20	  async function loadWorksheetConfig(): Promise<WorksheetConfig> {
21	    const config = await apiFetch<{
22	      data: {
23	        data_panel?: {
24	          worksheet_name?: string;
25	          available_days_column?: string;
26	          availability_column?: string;
27	          availability_value?: string;
28	        };
29	      } | null;
30	    }>('/api/config/workflow');
31	    return {
32	      worksheetName: config.data?.data_panel?.worksheet_name ?? null,
33	      availableDaysColumn: config.data?.data_panel?.available_days_column ?? null,
34	      availabilityColumn: config.data?.data_panel?.availability_column ?? null,
35	      availabilityValue: config.data?.data_panel?.availability_value ?? null,
36	    };
37	  }
38	
39	  let availabilityColumn = $state<string | null>(null);
40	  let availabilityValue = $state<string | null>(null);
41	  let availableRowSet = $derived(new Set(
42	    extractAvailableRows(dataStore.worksheetRows, availabilityColumn, availabilityValue)
43	  ));
44	
45	  function isAvailableRow(row: import('../lib/tableau').WorksheetRow): boolean {
46	    return availableRowSet.has(row);
47	  }
48	
49	  function toggleRow(row: import('../lib/tableau').WorksheetRow, checked: boolean): void {
50	    if (checked) {
51	      if (!dataStore.selectedRows.includes(row)) {
52	        dataStore.selectedRows = [...dataStore.selectedRows, row];
53	      }
54	    } else {
55	      dataStore.selectedRows = dataStore.selectedRows.filter((r) => r !== row);
56	    }
57	  }
58	
59	  async function loadWorksheetData(
60	    worksheetName: string,
61	    config: WorksheetConfig
62	  ): Promise<void> {
63	    dataStore.worksheetState = 'loading';
64	    try {
65	      dataStore.worksheetRows = await getWorksheetData(worksheetName);
66	      dataStore.availableDays = extractAvailableDays(dataStore.worksheetRows, config.availableDaysColumn);
67	      availabilityColumn = config.availabilityColumn;
68	      availabilityValue = config.availabilityValue;
69	      dataStore.selectedRows = [];
70	      dataStore.worksheetState = 'done';
71	    } catch {
72	      // Generic message — never expose raw error details to the consultant (AC4)
73	      dataStore.availableDays = null;
74	      dataStore.worksheetError = 'Could not load worksheet data';
75	      dataStore.worksheetState = 'error';
76	    }
77	  }
78	
79	  async function loadTasks(): Promise<void> {
80	    dataStore.tasksState = 'loading';
81	    try {
82	      const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', {
83	        headers: sessionHeaders(),
84	      });
85	      dataStore.tasks = response.data;
86	      dataStore.tasksState = 'done';
87	    } catch (err) {
88	      const msg =
89	        err instanceof ApiError
90	          ? err.message
91	          : err instanceof Error
92	            ? err.message
93	            : 'Could not load task list';
94	      dataStore.tasksError = msg;
95	      dataStore.tasksState = 'error';
96	    }
97	  }
98	
99	  onMount(() => {
100	    let active = true; // abort guard — prevents stale promise writes on rapid remount
101	
102	    (async () => {
103	      // Distinguish config fetch failure from worksheet simply not being configured
104	      let worksheetConfig: WorksheetConfig | null = null;
105	      let configFetchError: string | null = null;
106	      try {
107	        worksheetConfig = await loadWorksheetConfig();
108	      } catch (err) {
109	        configFetchError =
110	          err instanceof ApiError ? err.message : 'Could not load configuration';
111	      }
112	
113	      if (!active) return;
114	
115	      const worksheetName = worksheetConfig?.worksheetName ?? null;
116	
117	      // Both fetches run independently — one failure must not block the other (NFR9)
118	      const worksheetPromise = worksheetName && worksheetConfig
119	        ? loadWorksheetData(worksheetName, worksheetConfig)
120	        : (() => {
121	            dataStore.worksheetError = configFetchError ?? 'Worksheet name not configured';
122	            dataStore.worksheetState = 'error';
123	            return Promise.resolve();
124	          })();
125	
126	      await Promise.allSettled([worksheetPromise, loadTasks()]);
127	    })();
128	
129	    return () => {
130	      active = false; // cancel on unmount
131	    };
132	  });
133	</script>
